def parse_timeout(value, default=30):
    """Parse an optional timeout value."""
    if value is None:
        return default
    return int(value)

from src.config import parse_timeout

def test_integer_text():
    assert parse_timeout('12') == 12

def test_none_uses_default():
    assert parse_timeout(None, 9) == 9

