import pytest
from src.config import parse_timeout

def test_empty_text_uses_default():
    assert parse_timeout('', 7) == 7

def test_whitespace_uses_default():
    assert parse_timeout('   ', 8) == 8

def test_zero_is_preserved():
    assert parse_timeout('0', 5) == 0

def test_bad_text_still_fails():
    with pytest.raises(ValueError):
        parse_timeout('later')
